"""Durable model-load acceptance with generated bytes and fake callbacks only."""
import os
from pathlib import Path

import pytest

from scripts import audio_segments as audio
from scripts import transcript_results as results
from scripts.asr_sweep import SweepEngine


class Clock:
    def __init__(self):
        self.mono, self.wall = 0.0, 1000.0

    def advance(self, seconds):
        self.mono += seconds
        self.wall += seconds


def closed(data):
    folder = data / "audio_budget_2000-01-01"
    folder.mkdir()
    number, source = audio.reserve_segment(data, folder)
    with source.open("xb") as stream:
        stream.write(b"generated-model-budget" * 256)
        stream.flush()
        os.fsync(stream.fileno())
    audio.publish_closed(data, folder, source, number, 100.0, 160.0)
    return folder, source


def make(data, clock, prepare, **kwargs):
    return SweepEngine(data, recognize=lambda _path: pytest.fail("no source attempt authorized"),
                       prepare_model=prepare, monotonic=lambda: clock.mono,
                       wall_time=lambda: clock.wall, scan_seconds=100.0, **kwargs)


def saved(data):
    return audio.read_json(data / ".local_app/asr/retry.json")["model"]


def retained(data, folder, source):
    assert source.read_bytes() == b"generated-model-budget" * 256
    assert not results.attempt_path(data, folder, source.name).exists()
    with results.writer(data):
        pass
    assert not list(data.rglob("*.tmp"))


@pytest.mark.parametrize("exit_type", [SystemExit, KeyboardInterrupt])
def test_interrupted_load_is_durable_and_has_one_finite_restart_budget(tmp_path, exit_type):
    folder, source = closed(tmp_path)
    clock, loads = Clock(), []

    def abort():
        model = saved(tmp_path)
        loads.append(model["attempts"])
        assert model["attempts"] == model["lifetime"] == len(loads)
        assert model["wait_seconds"] == (30, 120, 300)[len(loads) - 1]
        assert model["next_at"] == clock.wall + model["wait_seconds"]
        raise exit_type("generated loading exit; not caught by the engine")

    for number, delay in enumerate((30, 120, 300), 1):
        engine = make(tmp_path, clock, abort)
        try:
            with pytest.raises(exit_type):
                engine.step()
        finally:
            engine.close()
        retained(tmp_path, folder, source)
        # A new engine at exactly the same clocks cannot reenter the loader.
        restarted = make(tmp_path, clock, abort)
        try:
            restarted.step()
            assert loads == list(range(1, number + 1))
            assert saved(tmp_path)["attempts"] == number
            if number < 3:
                assert restarted.snapshot()["next_retry_at"] == clock.wall + delay
            else:
                assert restarted.snapshot()["next_condition"] == "explicit_retry_or_dependency_change"
        finally:
            restarted.close()
        clock.advance(delay)
    clock.advance(100000)
    for _ in range(2):
        engine = make(tmp_path, clock, abort)
        try:
            engine.step()
            assert saved(tmp_path)["attempts"] == 3 and loads == [1, 2, 3]
        finally:
            engine.close()
    retained(tmp_path, folder, source)


@pytest.mark.parametrize("write_reached_disk", [False, True])
def test_unconfirmed_reservation_never_enters_model_or_source(tmp_path, monkeypatch, write_reached_disk):
    folder, source = closed(tmp_path)
    clock, loads = Clock(), []
    engine = make(tmp_path, clock, lambda: loads.append(1))
    original = audio.atomic_json

    def fail(path, value):
        if Path(path) == engine.path:
            if write_reached_disk:
                original(path, value)
            raise PermissionError("generated reservation confirmation failure")
        return original(path, value)

    monkeypatch.setattr(audio, "atomic_json", fail)
    try:
        engine.step()
        assert loads == [] and engine.snapshot()["error"] == "retry_state_unavailable"
        if write_reached_disk:
            assert saved(tmp_path)["attempts"] == 1 and saved(tmp_path)["wait_seconds"] == 30
        else:
            assert not engine.path.exists()
        retained(tmp_path, folder, source)
    finally:
        engine.close()


def test_handled_failure_settles_once_and_starts_cooldown_at_failure(tmp_path):
    folder, source = closed(tmp_path)
    clock, loads = Clock(), []

    def fail():
        loads.append(saved(tmp_path)["attempts"])
        clock.advance(5)
        raise RuntimeError("generated handled model failure")

    first = make(tmp_path, clock, fail)
    try:
        first.step()
        assert loads == [1]
        assert saved(tmp_path)["attempts"] == saved(tmp_path)["lifetime"] == 1
        assert saved(tmp_path)["next_at"] == 1035.0
    finally:
        first.close()
    restarted = make(tmp_path, clock, fail)
    try:
        restarted.step()
        assert loads == [1] and restarted.snapshot()["next_retry_at"] == 1035.0
    finally:
        restarted.close()
    clock.advance(30)
    restarted = make(tmp_path, clock, fail)
    try:
        restarted.step()
        assert loads == [1, 2]
        assert saved(tmp_path)["attempts"] == saved(tmp_path)["lifetime"] == 2
        assert saved(tmp_path)["wait_seconds"] == 120 and saved(tmp_path)["next_at"] == 1160.0
    finally:
        restarted.close()
    retained(tmp_path, folder, source)


def test_success_settlement_allows_clean_restarts_without_failure_exhaustion(tmp_path):
    folder, source = closed(tmp_path)
    clock, loads, stopped = Clock(), [], [False]

    def prepare():
        model = saved(tmp_path)
        assert model["attempts"] == 1 and model["lifetime"] == len(loads) + 1
        loads.append(1)
        stopped[0] = True

    for _ in range(5):
        stopped[0] = False
        engine = make(tmp_path, clock, prepare, should_stop=lambda: stopped[0])
        try:
            engine.step()
            assert engine.snapshot()["state"] == "stopping"
            model = saved(tmp_path)
            assert model["attempts"] == model["wait_seconds"] == model["next_at"] == 0
            assert model["lifetime"] == len(loads)
            assert engine.snapshot()["next_condition"] == "periodic_scan"
        finally:
            engine.close()
    assert len(loads) == 5
    retained(tmp_path, folder, source)


def test_unconfirmed_success_settlement_keeps_source_unaccepted(tmp_path, monkeypatch):
    folder, source = closed(tmp_path)
    clock, loads, saves = Clock(), [], []
    engine = make(tmp_path, clock, lambda: loads.append(1))
    original = audio.atomic_json

    def fail_settlement(path, value):
        if Path(path) == engine.path:
            saves.append(value["model"]["attempts"])
            if len(saves) == 2:
                raise PermissionError("generated success settlement failure")
        return original(path, value)

    monkeypatch.setattr(audio, "atomic_json", fail_settlement)
    try:
        engine.step()
        assert loads == [1] and saves == [1, 0]
        assert engine.snapshot()["error"] == "retry_state_unavailable"
        assert saved(tmp_path)["attempts"] == 1
        retained(tmp_path, folder, source)
    finally:
        engine.close()
    restarted = make(tmp_path, clock, lambda: pytest.fail("unsettled load skipped cooldown"))
    try:
        restarted.step()
        assert restarted.snapshot()["next_retry_at"] == 1030.0
        retained(tmp_path, folder, source)
    finally:
        restarted.close()
